python3 -c "
import json
with open('/Users/<REDACTED>/projects/mobile-agent-bench/results/maestro/a1/run-3/transcript.jsonl') as f:
    for line in f:
        d = json.loads(line)
        if d.get('type') == 'assistant':
            msg = d['message']
            for c in msg.get('content', []):
                if c.get('type') == 'tool_use':
                    print('TOOL_USE:', c['name'], json.dumps(c['input'])[:300])
                if c.get('type') == 'text':
                    print('TEXT:', c['text'][:300])
        if d.get('type') == 'user':
            msg = d['message']
            content = msg.get('content')
            if isinstance(content, list):
                for c in content:
                    if c.get('type') == 'tool_result':
                        cont = c.get('content')
                        if isinstance(cont, list):
                            for cc in cont:
                                if cc.get('type') == 'text':
                                    print('  RESULT:', cc['text'][:300])
"
